mapper.select:
SELECT COUNT(*)
FROM brick_test_suite_run r
INNER JOIN brick_test_suite s ON s.id = r.suite_id
WHERE s.is_deleted = 0
AND r.suite_id = #{testSuiteId}
AND s.swagger_mapping_id = #{swaggerMappingId}
AND s.name LIKE CONCAT('%', #{suiteName}, '%')
AND r.status = #{status}
AND r.start_time >= #{startDate}
AND r.start_time <= #{endDate}
